from pathlib import Path
root=Path('build-piiwii-documents-060/work')
def rw(path,pairs):
    p=root/path; s=p.read_text()
    for a,b in pairs:
        if a not in s:
            raise SystemExit(f'Missing expected text in {path}: {a[:80]}')
        s=s.replace(a,b)
    p.write_text(s)
